// Picks the buddy app's language and fills in its text. Copy lives in strings.js (generated by
// i18n/buddy.py). Order: the site's language-picker cookie, then the browser's languages, then
// English. LANG uses the website's codes (es-ES, zh-Hant…), which the server's langOf() accepts.
import { STRINGS } from './strings.js';

function match(tag) {
  const [base, ...rest] = tag.toLowerCase().replace(/_/g, '-').split('-');
  let code;
  if (base === 'zh') code = rest.some(p => ['hant', 'tw', 'hk', 'mo'].includes(p)) ? 'zh-Hant' : 'zh-Hans';
  else if (base === 'es') code = rest.includes('es') ? 'es-ES' : 'es-MX';
  else if (base === 'pt') code = 'pt-BR';
  else code = base;
  return STRINGS[code] ? code : null;
}

function detect() {
  const cookie = k => (document.cookie.match('(?:^|; )' + k + '=([^;]*)') || [])[1];
  const lang = cookie('firebase-language-override');
  if (lang) return match(lang + (cookie('firebase-country-override') ? '-' + cookie('firebase-country-override') : '')) || 'en';
  for (const tag of navigator.languages || [navigator.language || 'en']) {
    const hit = match(tag);
    if (hit) return hit;
  }
  return 'en';
}

export const LANG = detect();

export function t(key, vars = {}) {
  const s = (STRINGS[LANG] && STRINGS[LANG][key]) || STRINGS.en[key] || key;
  return s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
}

// <el data-i18n="key"> sets text; data-i18n-html sets markup (for copy with <br>);
// data-i18n-attr="aria-label:key,title:key" sets attributes.
export function applyStatic(root = document) {
  document.documentElement.lang = LANG === 'es-MX' ? 'es-419' : LANG;
  document.title = t('page_title');
  root.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll('[data-i18n-html]').forEach(el => { el.innerHTML = t(el.dataset.i18nHtml); });
  root.querySelectorAll('[data-i18n-attr]').forEach(el => {
    el.dataset.i18nAttr.split(',').forEach(pair => {
      const [attr, key] = pair.split(':');
      el.setAttribute(attr.trim(), t(key.trim()));
    });
  });
}
